import { readFile, writeFile } from "node:fs/promises";

const catalog = JSON.parse(await readFile("supabase/catalog/smccd-2025-2026.json", "utf8"));
const outputPath = "supabase/migrations/20260710000000_smccd_curriculum.sql";

const sql = [];
sql.push(`-- Source-backed SMCCD curriculum imported from the official 2025-2026 catalogs.
-- Generated by scripts/generate-smccd-migration.mjs from supabase/catalog/smccd-2025-2026.json.

create table public.smccd_colleges (
  code text primary key,
  name text not null,
  catalog_year text not null,
  courses_url text not null,
  programs_url text not null,
  concurrent_enrollment_url text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.smccd_courses (
  id text primary key,
  college_code text not null references public.smccd_colleges(code) on delete cascade,
  course_code text not null,
  subject text not null,
  course_number text not null,
  title text not null,
  units_min numeric(5,2) not null check (units_min >= 0),
  units_max numeric(5,2) check (units_max is null or units_max >= units_min),
  degree_applicable boolean not null default true,
  transfer_credit text check (transfer_credit in ('CSU', 'UC', 'CSU/UC')),
  attributes text[] not null default '{}',
  catalog_url text not null,
  source_year text not null,
  created_at timestamptz not null default now(),
  unique (college_code, course_code)
);

create index smccd_courses_lookup_idx on public.smccd_courses(college_code, subject, course_code);
create index smccd_courses_title_idx on public.smccd_courses using gin (to_tsvector('english', course_code || ' ' || title));

create table public.smccd_programs (
  id text primary key,
  college_code text not null references public.smccd_colleges(code) on delete cascade,
  program_code text not null,
  title text not null,
  award_type text not null check (award_type in ('AA', 'AS')),
  total_degree_units numeric(5,2) not null default 60,
  total_major_units_text text not null default '',
  catalog_url text not null,
  source_year text not null,
  created_at timestamptz not null default now(),
  unique (college_code, program_code)
);

create table public.smccd_program_requirements (
  id text primary key,
  program_id text not null references public.smccd_programs(id) on delete cascade,
  label text not null,
  kind text not null check (kind in ('all', 'choose_units', 'choose_count', 'or_group', 'text_rule')),
  min_units numeric(5,2),
  min_count integer,
  raw_text text,
  sort_order integer not null default 0
);

create table public.smccd_requirement_courses (
  id uuid primary key default gen_random_uuid(),
  requirement_id text not null references public.smccd_program_requirements(id) on delete cascade,
  course_code text not null,
  units_text text not null default '',
  note text,
  unique (requirement_id, course_code)
);

create table public.student_smccd_goals (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  program_id text not null references public.smccd_programs(id) on delete cascade,
  is_primary boolean not null default true,
  notes text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, program_id)
);

create unique index student_smccd_goals_one_primary
  on public.student_smccd_goals(user_id)
  where is_primary;

alter table public.plan_courses
  add column smccd_course_id text references public.smccd_courses(id) on delete set null;

create index plan_courses_smccd_course_idx on public.plan_courses(smccd_course_id);
create trigger student_smccd_goals_set_updated_at before update on public.student_smccd_goals
for each row execute procedure public.set_updated_at();

alter table public.smccd_colleges enable row level security;
alter table public.smccd_courses enable row level security;
alter table public.smccd_programs enable row level security;
alter table public.smccd_program_requirements enable row level security;
alter table public.smccd_requirement_courses enable row level security;
alter table public.student_smccd_goals enable row level security;

create policy "SMCCD colleges are readable" on public.smccd_colleges for select to authenticated using (true);
create policy "SMCCD courses are readable" on public.smccd_courses for select to authenticated using (true);
create policy "SMCCD programs are readable" on public.smccd_programs for select to authenticated using (true);
create policy "SMCCD requirements are readable" on public.smccd_program_requirements for select to authenticated using (true);
create policy "SMCCD requirement courses are readable" on public.smccd_requirement_courses for select to authenticated using (true);
create policy "users manage own SMCCD goals" on public.student_smccd_goals for all to authenticated
using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);

comment on table public.smccd_courses is 'Source-backed 2025-2026 course catalog rows. Catalog inclusion does not guarantee term availability or high-school approval.';
comment on table public.smccd_programs is 'Source-backed AA/AS program definitions for planning only; not an official degree audit.';
`);

sql.push(insertValues(
  "public.smccd_colleges (code, name, catalog_year, courses_url, programs_url, concurrent_enrollment_url)",
  catalog.sources.map((source) => [source.code, source.name, catalog.catalogYear, source.coursesUrl, source.programsUrl, "https://smccd.edu/k-12/"])
));

for (const batch of chunks(catalog.courses, 200)) {
  sql.push(insertValues(
    "public.smccd_courses (id, college_code, course_code, subject, course_number, title, units_min, units_max, degree_applicable, transfer_credit, attributes, catalog_url, source_year)",
    batch.map((course) => [
      `${course.collegeCode}:${course.courseCode}`,
      course.collegeCode,
      course.courseCode,
      course.subject,
      course.number,
      course.title,
      course.unitsMin,
      course.unitsMax,
      course.degreeApplicable,
      course.transferCredit,
      { sql: `array[${course.attributes.map(quote).join(", ")}]::text[]` },
      course.catalogUrl,
      catalog.catalogYear
    ])
  ));
}

for (const batch of chunks(catalog.programs, 150)) {
  sql.push(insertValues(
    "public.smccd_programs (id, college_code, program_code, title, award_type, total_degree_units, total_major_units_text, catalog_url, source_year)",
    batch.map((program) => [
      `${program.collegeCode}:${program.programCode}`,
      program.collegeCode,
      program.programCode,
      program.title,
      program.awardType,
      program.totalDegreeUnitsRequired,
      program.totalMajorUnitsText,
      program.catalogUrl,
      catalog.catalogYear
    ])
  ));
}

const requirements = catalog.programs.flatMap((program) => program.requirementGroups.map((requirement, index) => ({
  ...requirement,
  id: `${program.collegeCode}:${program.programCode}:${requirement.id}`,
  programId: `${program.collegeCode}:${program.programCode}`,
  sortOrder: index
})));
for (const batch of chunks(requirements, 200)) {
  sql.push(insertValues(
    "public.smccd_program_requirements (id, program_id, label, kind, min_units, min_count, raw_text, sort_order)",
    batch.map((requirement) => [
      requirement.id,
      requirement.programId,
      requirement.label,
      requirement.kind,
      requirement.minUnits,
      requirement.minCount,
      requirement.rawText,
      requirement.sortOrder
    ])
  ));
}

const options = requirements.flatMap((requirement) => requirement.courseOptions.map((option) => ({
  requirementId: requirement.id,
  courseCode: option.courseCode,
  unitsText: option.unitsText,
  note: option.note
})));
for (const batch of chunks(options, 250)) {
  sql.push(insertValues(
    "public.smccd_requirement_courses (requirement_id, course_code, units_text, note)",
    batch.map((option) => [option.requirementId, option.courseCode, option.unitsText, option.note])
  ));
}

await writeFile(outputPath, `${sql.join("\n").trimEnd()}\n`);
console.log(`Wrote ${outputPath}: ${catalog.courses.length} courses, ${catalog.programs.length} programs, ${requirements.length} requirement groups, ${options.length} course options.`);

function insertValues(tableAndColumns, rows) {
  if (rows.length === 0) return "";
  return `insert into ${tableAndColumns} values\n${rows.map((row) => `  (${row.map(sqlValue).join(", ")})`).join(",\n")}\non conflict do nothing;\n`;
}

function sqlValue(value) {
  if (value && typeof value === "object" && "sql" in value) return value.sql;
  if (value === null || value === undefined || value === "") return value === "" ? "''" : "null";
  if (typeof value === "number") return Number.isFinite(value) ? String(value) : "null";
  if (typeof value === "boolean") return value ? "true" : "false";
  return quote(String(value));
}

function quote(value) {
  return `'${value.replaceAll("'", "''")}'`;
}

function chunks(items, size) {
  const result = [];
  for (let index = 0; index < items.length; index += size) result.push(items.slice(index, index + size));
  return result;
}
